def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != bg]
    if len(colors) != 1:
        return [row[:] for row in grid]
    fg = colors[0]
    pts = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == fg]
    if not pts: return [row[:] for row in grid]
    rmin,rmax = min(r for r,c in pts), max(r for r,c in pts)
    cmin,cmax = min(c for r,c in pts), max(c for r,c in pts)
    row_counts = [sum(row[c] == fg for c in range(w)) for row in grid]
    occupied_rows = [r for r,n in enumerate(row_counts) if n]
    active_rows = {r for r,n in enumerate(row_counts) if n >= 4}
    for r in (occupied_rows[0], occupied_rows[-1]):
        if row_counts[r] >= 2:
            active_rows.add(r)
    col_counts = [sum(grid[r][c] == fg for r in range(h)) for c in range(w)]
    active_cols = {c for c,n in enumerate(col_counts) if n >= 2 and any(grid[r][c] == fg and r not in active_rows for r in range(h))}
    out = [row[:] for row in grid]
    for r in active_rows:
        for c in range(cmin,cmax+1):
            if out[r][c] == bg: out[r][c] = 2
    for c in active_cols:
        for r in range(rmin,rmax+1):
            if out[r][c] == bg: out[r][c] = 2
    return out

